cat << 'EOF' > update-registry.js
const fs = require('fs');

let registryPath = '/var/tmp/loop-bench/runs/0c7c6cb0757d/workspace/target/src/orchestration/tools/registry.ts';
let registryText = fs.readFileSync(registryPath, 'utf8');

registryText = registryText.replace("import {Ajv} from 'ajv';", "import Ajv from 'ajv';");
registryText = registryText.replace(
  "throw new Error(`Invalid inputSchema for tool \"${toolName}\": ${(error as Error).message}`);",
  "throw new Error(`Invalid inputSchema for tool \"${toolName}\": ${(error as Error).message}`, {cause: error});"
);
fs.writeFileSync(registryPath, registryText);

let testPath = '/var/tmp/loop-bench/runs/0c7c6cb0757d/workspace/target/src/orchestration/tools/registry.acceptance.test.ts';
let testText = fs.readFileSync(testPath, 'utf8');

testText = testText.replace(
  `        if (round === 2) {
          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield {type: 'stop', stopReason: 'end_turn'};`,
  `        if (round !== 2) {
          yield {type: 'text', text: '22C in Paris'};
          yield {type: 'stop', stopReason: 'end_turn'};
          return;
        }
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        const [firstContent] = lastMessage.content;
        firstRoundToolResult = firstContent?.content ?? '';
        yield {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
        };
        yield {type: 'stop', stopReason: 'tool_use'};`
);

fs.writeFileSync(testPath, testText);
EOF
node update-registry.js

